package com.vnshop.invoiceservice.infrastructure.dlt;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*; import java.util.concurrent.TimeUnit; import org.apache.kafka.clients.consumer.ConsumerRecord; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
 @Service public class DurableDltService { private final DurableDltRepository repo; public DurableDltService(DurableDltRepository r){repo=r;} @Transactional public void store(ConsumerRecord<String,String> r,String reason,int attempts){String p=r.value()==null?"":r.value();String h=HexFormat.of().formatHex(hash(p));repo.findByTopicAndPartitionAndOffsetAndPayloadHash(r.topic(),r.partition(),r.offset(),h).orElseGet(()->repo.save(new DurableDltJpaEntity(r.topic(),r.partition(),r.offset(),r.key(),p,h,reason,attempts,Instant.now())));} @Transactional public void replay(UUID id,KafkaTemplate<String,Object> kafka){DurableDltJpaEntity e=repo.findById(id).orElseThrow();if(e.getReplayedAt()!=null)throw new DurableDltReplayConflictException(id);Instant c=Instant.now();if(repo.claim(id,c,c.plusSeconds(60))!=1)throw new DurableDltReplayConflictException(id);try{kafka.send(e.getTopic().replaceFirst("\\.DLT$",""),e.getRecordKey(),e.getPayload()).get(10,TimeUnit.SECONDS);if(repo.mark(id,c,Instant.now())!=1)throw new DurableDltReplayConflictException(id);}catch(InterruptedException x){Thread.currentThread().interrupt();repo.release(id,c);throw new IllegalStateException("DLT replay interrupted",x);}catch(DurableDltReplayConflictException x){repo.release(id,c);throw x;}catch(Exception x){repo.release(id,c);throw new IllegalStateException("DLT replay failed",x);}} private static byte[] hash(String s){try{return MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}} }
